cd /workspace && python3 - <<'PYEOF'
import sys, itertools
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/tmp')
import exact as E

links=[(3, 6, 3), (0, 2, 2), (3, 7, 0), (6, 7, 2), (0, 1, 3), (0, 4, 1), (0, 6, 1), (1, 2, 0), (5, 6, 2), (2, 3, 3), (1, 6, 1), (0, 5, 0), (4, 6, 2), (2, 5, 1), (5, 7, 1), (1, 7, 3)]
parts=[1,5,7]; demand={1:2,5:3,7:2}
linkuv=[(u,v) for (u,v,c) in links]; cap=[c for (u,v,c) in links]
n=8
trees_by_root={}
for v in parts:
    if demand[v]>0:
        trees_by_root[v]=E.weighted_trees(E.arborescences(parts,v), demand[v])
paths=E.split_paths(n, linkuv, cap, parts)
names={(l,d):f"{u}{v}->{u2}{v2}" for (l,d),( (u,v), (u2,v2)) in zip([(l,d) for l,(u,v) in enumerate(linkuv) for d in (0,1)], [( (linkuv[l][0],linkuv[l][1]), (linkuv[l][1] if d==0 else linkuv[l][0], linkuv[l][0] if d==0 else linkuv[l][1])) for l in range(len(linkuv)) for d in (0,1)])}
def wname(w): return " ".join(f"L{a}d{b}" for (a,b) in w)
keys=list(trees_by_root)
print("trees per root:", {v:len(trees_by_root[v]) for v in keys})
for choice in itertools.product(*[trees_by_root[v] for v in keys]):
    L={}
    for v,wt in zip(keys,choice):
        for (tr,c) in wt:
            for (u,w) in tr: L[(u,w)]=L.get((u,w),0)+c
    dem={k:val for k,val in L.items() if val>0}
    if any(not paths.get(k) for k in dem): continue
    if E.route_ok(paths, dem, cap, linkuv):
        print("SOLUTION trees:", choice)
        print("L:", dem)
        for k in sorted(dem):
            print("  pair", k, "demand", dem[k], "paths:", [wname(p) for p in paths[k]])
        break
PYEOF
